import {BODIES,LEVELS,reachable,serviceReachable,regionAt,footprint} from './architecture.js';
import {shortestWalk} from './navigation.js';
export class Automation{
 constructor(sim){this.sim=sim;this.enabled=false;this.interval=40;this.idle=0;this.exceptions=new Set();this.route=null;this.evacuating=false;this.routeIndex=1;this.error='';this.records=[];this.returnRequested=false;this.returnRegion=null;this.returnSteps=0;this.warningReal=0;this.reactionSeconds=5;this.remoteNotice=false;}
 requestReconnect(){const s=this.sim;if(s.mode!=='idle'||s.anyLiftActive)return false;const connected=serviceReachable(s.phase,s.experiment,s.safetyDoors).has(s.safetyRegion);if(connected){this.exceptions.delete(s.ownerRegion);s.message='既に通路へ接続されています。現在区画の例外を解除しました。';return true;}this.returnRequested=true;this.returnRegion=s.ownerRegion;this.returnSteps=0;this.exceptions.add(this.returnRegion);s.message='次の接続可能な周期まで、待機を挟まず物理搬送します。';return true;}
 allowed(){return this.exceptions.has(this.sim.ownerRegion);}
 safe(){const s=this.sim;const own=s.owner;if(s.isLiftOwner(own)&&!s.anyLiftActive&&LEVELS.includes(s.player.y))return true;if(!own||own.startsWith('joint:')||!s.targetReachable.has(s.safetyRegion))return false;for(let i=0;i<16;i++){const a=i*Math.PI/8;if(s.ownerAt(s.player.x+Math.cos(a)*.46,s.player.z+Math.sin(a)*.46)!==own)return false;}return true;}
 findRoute(){const s=this.sim,trial=Object.assign(Object.create(Object.getPrototypeOf(s)),s);trial.doors=Object.fromEntries(Object.keys(s.doors).map(k=>[k,k!=='R3-door']));trial.player={...s.player};trial.invalidate();const target=serviceReachable(s.next,s.experiment,trial.doors),candidates=[],seen=new Set();
  const add=(x,z)=>{if(!trial.isFree(x,z,s.player.y,.375))return;const region=trial.regionAtPoint(x,z,s.player.y);if(!target.has(region)||trial.ownerAt(x,z)?.startsWith('joint:'))return;const distance=Math.hypot(x-s.player.x,z-s.player.z);if(seen.has(region)){const old=candidates.find(c=>c.region===region);if(old.distance<=distance)return;Object.assign(old,{x,z,distance});}else{seen.add(region);candidates.push({x,z,distance,region});}};
  add(-1.2,4);for(const b of BODIES){const p=s.positions[b.id];if(Math.abs(p.y-s.player.y)>.01)continue;const f=footprint(b);for(let z=1;z<f.d;z+=1.6)for(let x=1;x<f.w;x+=1.6)add(Math.round((p.x+x)*5)/5,Math.round((p.z+z)*5)/5);}
  let best=null;for(const c of candidates.sort((a,b)=>a.distance-b.distance)){if(best&&c.distance>=best.distance)break;const route=shortestWalk(trial,{x:s.player.x,y:s.player.y,z:s.player.z},{x:c.x,y:s.player.y,z:c.z});if(route.ok&&(!best||route.distance<best.distance))best={...route,destinationRegion:c.region};}return best;
 }
 prepare(){this.sim.experience.event('warning',this.sim.owner);this.idle=0;this.route=null;this.error='';const s=this.sim;this.warningReal=0;this.remoteNotice=/^D[1-4]$/.test(s.owner??'');this.reactionSeconds=this.remoteNotice?8:5;this.noticeStep=0;s.warningDuration=this.reactionSeconds*s.speed;if(!this.safe()&&!this.allowed()){this.route=this.findRoute();if(!this.route){this.fail('身体幅と床支持を満たす退避経路がありません。搬送計画の見直しが必要です。');return false;}s.warningDuration=this.reactionSeconds*s.speed+.65*s.speed+this.route.distance/5.2;s.message=this.remoteNotice?'帰還便S1は8秒後に出発準備へ入ります。搬送室へ戻ってください。':'施設放送：この区画は次周期で孤立します。退避経路へ移動してください。';}return true;}
 fail(message){this.error=message;this.enabled=false;this.returnRequested=false;this.evacuating=false;this.sim.mode='idle';this.sim.plan=null;this.sim.message='安全確認で運行停止：'+message;}
 begin(){const s=this.sim;if(this.safe()||this.allowed()&&!s.owner?.startsWith('joint:'))return false;s.experience.leave();s.experience.end();s.experience.focus=null;s.experience.blend=0;this.route=this.findRoute();if(!this.route){this.fail('退避経路が失われました。座標ワープは行いません。');return true;}
  // Ordinary safety doors are explicitly opened before route replay. These are
  // never permanent invisible passages, and each door keeps its own animation.
  for(const id of Object.keys(s.doors))if(id!=='R3-door')s.experience.doorTargets[id]=true;this.routeIndex=1;this.evacuating=true;s.mode='auto-evacuate';s.message='施設放送：安全通路へ退避します。';this.records.push({from:{...s.player},route:this.route,completed:false});return true;
 }
 tick(dt){const s=this.sim;if(s.mode==='warning'){this.warningReal+=dt;if(this.remoteNotice&&this.warningReal>=4&&!this.safe()&&this.noticeStep===0){this.noticeStep=1;s.message='帰還便S1の出発準備まで、あと4秒です。戻れない場合は安全退避します。';}}if(!this.evacuating){if(s.mode==='idle'&&this.returnRequested){if(reachable(s.phase,s.experiment,s.safetyDoors).has(s.safetyRegion)){this.exceptions.delete(this.returnRegion);this.returnRequested=false;s.message='物理的に再接続しました。残留例外を解除します。';}else if(this.returnSteps>=3){this.returnRequested=false;this.fail('三周期以内に再接続する計画がありません。');}else if(s.startTransfer())this.returnSteps++;else this.fail('再接続搬送を開始できません：'+s.message);return;}if(s.mode==='idle'&&this.enabled){this.idle+=dt;if(this.idle>=this.interval&&!s.anyLiftActive)s.startTransfer();}if(s.mode==='warning'&&this.warningReal>=this.reactionSeconds&&!this.safe()&&!this.allowed())this.begin();return;}
  if(Object.entries(s.experience.doorProgress).some(([id,v])=>s.experience.doorTargets[id]&&v<.999))return;
  let remaining=5.2*dt*s.speed;while(remaining>1e-7&&this.routeIndex<this.route.path.length){const p=this.route.path[this.routeIndex],dx=p.x-s.player.x,dz=p.z-s.player.z,d=Math.hypot(dx,dz);if(d<1e-6){this.routeIndex++;continue;}const step=Math.min(.05,d,remaining),before={...s.player};s.move(dx/d*step,dz/d*step);const moved=Math.hypot(s.player.x-before.x,s.player.z-before.z);if(moved<step*.8){this.fail('退避経路の身体移動が障害物で停止しました。');return;}remaining-=moved;}
  if(this.routeIndex>=this.route.path.length){if(!this.safe()){this.fail('退避先が次周期の安全区域ではありません。');return;}this.evacuating=false;this.records.at(-1).completed=true;s.mode='warning';s.elapsed=s.warningDuration;s.message='安全通路へ退避しました。';s.beginClosing();}
 }
}
